const items = $input.all().map(i => i.json);
const signalCounts = {};
for (const a of items) {
  for (const tag of (a.marketSignals || [])) signalCounts[tag] = (signalCounts[tag] || 0) + 1;
}
const ragDocs = items.map(a => ({
  title: a.title,
  url: a.url,
  urlDecoded: a.urlDecoded,
  sourceName: a.sourceName,
  publishedAt: a.publishedAt,
  marketSignals: a.marketSignals,
  agentSummary: a.agentSummary
}));
return [{ json: { totalArticles: items.length, decodedCount: items.filter(x => x.urlDecoded).length, signalCounts, ragDocs } }];
